381	Our second state-dependent distance,
382	defined next,
383	is more analytic.
384	
385	\begin{definition}
386	Let $\{Q^x_a\}$ and $\{R^x_a\}$ be sets of matrices in $\mathcal{L}(\mathcal{H})$.
387	Let $\calD$ be a distribution on the variables~$x$ and $\ket{\psi}$ be a state in $\mathcal{H}$.
388	Then we say that \emph{$Q^x_a \approx_{\delta} R^x_a$ on state $\ket{\psi}$ and distribution $\calD$} if
389	\begin{equation*}
390	\E_{\bx \sim \calD} \sum_a \Vert (Q_{a}^{\bx} - R_{a}^{\bx} ) \ket{\psi}\Vert^2 = O(\delta).
391	\end{equation*}
392	\end{definition}
393	
394	As above, we will sometimes leave the state or distribution unspecified when clear from context.
395	This is sometimes referred to as \emph{the} state-dependence distance,
396	whereas our first distance measure is often referred to as the ``consistency".
397	A typical setting of parameters is $\mathcal{H} = \mathcal{H}_A \otimes \mathcal{H}_B$,
398	$Q^x_a := A^x_a \otimes I_{\reg{Bob}}$,
399	and $R^x_a := I_{\reg{Alice}} \otimes B^x_a$.
400	In this case, we have the following relationship between the two state-dependent distances.
401	
402	\begin{fact}\label{fact:agreement}
403	Let $\{A^x_a\}$ and $\{B^x_a\}$ be POVM measurements.
404	The following two facts hold.
405	\begin{enumerate}
406	\item If $A^x_a \otimes I_{\reg{Bob}} \consistency_{\delta} I_{\reg{Alice}} \otimes B^x_a$
407		then $A^x_a \otimes I_{\reg{Bob}} \approx_{\delta} I_{\reg{Alice}} \otimes B^x_a$.
408	\item If $A^x_a \otimes I_{\reg{Bob}} \approx_{\delta} I_{\reg{Alice}} \otimes B^x_a$ \emph{and} $\{A^x_a\}$ and $\{B^x_a\}$ are projective measurements,
409		then $A^x_a \otimes I_{\reg{Bob}} \consistency_{\delta} I_{\reg{Alice}} \otimes B^x_a$.\label{item:partial-converse}
410	\end{enumerate}
411	\end{fact}
412	\begin{proof}
413	Suppose that $A^x_a \otimes I_{\reg{Bob}} \consistency_{\delta} I_{\reg{Alice}} \otimes B^x_a$.
414	This is equivalent to the statement
415	\begin{equation}\label{eq:i-derived-a-formula}
416	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes B^{\bx}_a \ket{\psi} \geq 1- O(\delta).
417	\end{equation}
418	As a result, using the fact that~$A$ and~$B$ are POVMs,
419	\begin{align}
420	\E_{\bx} \sum_a \Vert (A_{a}^{\bx}\otimes I - I \otimes B_{a}^{\bx} ) \ket{\psi}\Vert^2 
421	& = \E_{\bx} \sum_a \bra{\psi} ((A_{a}^{\bx})^2\otimes I + I \otimes (B_{a}^{\bx})^2 - 2 A_a^{\bx} \otimes B_{a}^{\bx}) \ket{\psi}\nonumber\\
422	& \leq \E_{\bx} \sum_a \bra{\psi} (A_{a}^{\bx}\otimes I + I \otimes B_{a}^{\bx} - 2 A_a^{\bx} \otimes B_{a}^{\bx}) \ket{\psi}\label{eq:sometimes-tight}\\
423	& = 2 - 2 \E_{\bx} \sum_a \bra{\psi} A_a^{\bx} \otimes B_{a}^{\bx} \ket{\psi}\nonumber.
424	\end{align}
425	By \Cref{eq:i-derived-a-formula}, this is $O(\delta)$.
426	As a result, $A^x_a \otimes I_{\reg{Bob}} \approx_{\delta} I_{\reg{Alice}} \otimes B^x_a$.
427	The reverse statement holds when~$A$ and~$B$ are projective measurements
428	because \Cref{eq:sometimes-tight} is an equality in this case.
429	\end{proof}
430	
431	The following fact shows that we can derive a weaker converse in the case when only one of~$A$ or~$B$ is projective.
432	
433	\begin{fact}\label{fact:almost-agreement}
434	Suppose $\{A^x_a\}$ and $\{B^x_a\}$ are two measurements such that $A^x_a \otimes I_{\reg{Bob}} \approx_{\delta} I_{\reg{Alice}} \otimes B^x_a$.
435	Suppose further that either~$A$ or~$B$ is a projective measurement (and the other is a POVM measurement).
436	Then $A^x_a \otimes I_{\reg{Bob}} \consistency_{\delta^{1/2}} I_{\reg{Alice}} \otimes B^x_a$.
437	\end{fact}
438	\begin{proof}
439	Our goal is to upper bound the expression
440	\begin{equation}\label{eq:anand-is-a-stable-genius-yet-again}
441	1 - \E_\bx \sum_a \bra{\psi} A^{\bx}_a \otimes B^{\bx}_a \ket{\psi}.
442	\end{equation}
443	We begin by rewriting the number~$1$.
444	Here we use the fact that because~$A$ is projective, $(A^x_a)^2 = A^x_a$,
445	and so $\sum_a (A^x_a)^2 = I$.
446	This gives us:
447	\begin{align}
448	\eqref{eq:anand-is-a-stable-genius-yet-again}
449	& = \E_\bx \sum_a \bra{\psi} (A^{\bx}_a)^2 \otimes I_{\reg{Bob}} \ket{\psi} - \E_\bx \sum_a \bra{\psi} A^{\bx}_a \otimes B^{\bx}_a \ket{\psi}\nonumber\\
450	& = \E_\bx \sum_a \bra{\psi} (A^{\bx}_a \otimes I_{\reg{Bob}}) \cdot (A^{\bx}_a \otimes I_{\reg{Bob}} - I_{\reg{Alice}} \otimes B^{\bx}_a) \ket{\psi}\nonumber\\
451	& \leq \E_\bx \sum_a \Vert A^{\bx}_a \otimes I_{\reg{Bob}} \ket{\psi}\Vert \cdot \Vert(A^{\bx}_a \otimes I_{\reg{Bob}} - I_{\reg{Alice}} \otimes B^{\bx}_a) \ket{\psi}\Vert\label{eq:anand-continues-to-be-a-stable-genius}
452	\end{align}
453	Now we apply Cauchy-Schwarz and then Jensen's inequality:
454	\begin{equation*}
455	\eqref{eq:anand-continues-to-be-a-stable-genius}
456	\leq  \sqrt{\E_\bx \sum_a \Vert A^{\bx}_a \otimes I_{\reg{Bob}} \ket{\psi}\Vert^2
457		\cdot \sum_a \Vert(A^{\bx}_a \otimes I_{\reg{Bob}} - I_{\reg{Alice}} \otimes B^{\bx}_a) \ket{\psi}\Vert^2}
458	\end{equation*}
